update public.learning_paths
set
  title = 'Urban Sociology',
  goal = 'Urban Sociology',
  summary = 'Urban sociology provides a comprehensive examination of cities as social laboratories where inequality, culture, and infrastructure intersect. This course balances foundational theory with contemporary issues such as spatial inequality, urban governance, climate resilience, and planetary urbanization. Students will engage with spatial methods, policy analysis, and comparative global urbanism to understand the complex forces shaping modern metropolitan life.',
  data = $urbsjson${"slug": "urban-sociology", "title": "Urban Sociology", "description": "Urban sociology provides a comprehensive examination of cities as social laboratories where inequality, culture, and infrastructure intersect. This course balances foundational theory with contemporary issues such as spatial inequality, urban governance, climate resilience, and planetary urbanization. Students will engage with spatial methods, policy analysis, and comparative global urbanism to understand the complex forces shaping modern metropolitan life.", "topics": [{"id": "463229f2-bf4f-4a3b-bd21-4304e1c641dc", "type": "topic", "title": "The Urban Question and the Sociological Imagination", "description": "This opening topic frames cities as social laboratories where inequality, culture, institutions, infrastructure, and everyday life become visible.", "children": [{"id": "3a960fc6-49e9-4d1f-a3d6-82f4b2c18f3d", "type": "subtopic", "title": "Urban sociology as field", "children": [{"id": "c8dfe6e7-e133-475a-9c78-6c8e87921531", "type": "concept", "title": "City as social form"}, {"id": "6cda8a62-8f96-4ad2-a790-89cfcf36f245", "type": "concept", "title": "Spatial organization of social life"}, {"id": "908fc6da-800b-475d-b69e-d7b90ac79c60", "type": "concept", "title": "Urban problems as public issues"}], "description": "Students learn what makes urban sociology distinct from planning, geography, economics, and policy."}, {"id": "08661c68-482f-4b55-b7e4-0fa050d7eaa3", "type": "subtopic", "title": "Scale and place", "children": [{"id": "7de77312-d884-40d0-85fb-f2e4f238d70c", "type": "concept", "title": "Micro, neighborhood, metropolitan, and global scales"}, {"id": "270c8323-6162-4e7e-a223-83f1c738d1bf", "type": "concept", "title": "Place, space, and territory"}, {"id": "9a8357ed-0a86-4c46-ab29-c1da8d43993b", "type": "concept", "title": "Urban-rural and suburban relations"}], "description": "Urban life must be read across body, block, neighborhood, city, region, and global system."}, {"id": "4963f460-0e3a-447f-9244-8895129a458f", "type": "subtopic", "title": "Reading cities critically", "children": [{"id": "b2bc0339-9c29-48d9-9ecb-9b793719be2d", "type": "concept", "title": "Power and inequality"}, {"id": "5bc381fb-937c-45e9-aadd-39e26c618a7d", "type": "concept", "title": "Public versus private interests"}, {"id": "1a98c9ee-e8ac-4a1c-b91c-4331d9b03389", "type": "concept", "title": "Evidence, interpretation, and positionality"}], "description": "Students learn to ask who benefits from urban arrangements and who bears their costs."}]}, {"id": "eeee5cfb-97f5-405c-8093-899bcf9db7fa", "type": "topic", "title": "Urbanization, City Growth, and Metropolitan Systems", "description": "Urbanization is one of the central transformations of modern life. Students examine why cities grow, how metropolitan systems form, and how urbanization differs across historical and global settings.", "children": [{"id": "1538794e-ea99-41a6-84a9-523f8bddc117", "type": "subtopic", "title": "Urbanization processes", "children": [{"id": "aced391e-22bc-4123-83e3-902c57988331", "type": "concept", "title": "Rural-to-urban migration"}, {"id": "bca3b22f-8d87-4187-9b5c-3e8052700baa", "type": "concept", "title": "Industrial and postindustrial urbanization"}, {"id": "e665fb37-b578-482f-ad93-6e3cc6d1cf26", "type": "concept", "title": "Demographic transition and megacities"}], "description": "Students connect migration, industrialization, state policy, and capital flows to city growth."}, {"id": "439777be-34c4-453d-ac90-5bf5c08e41a0", "type": "subtopic", "title": "Metropolitan regions", "children": [{"id": "1530594b-4fc3-48ed-8266-17f6417a6dfc", "type": "concept", "title": "Central cities and suburbs"}, {"id": "41f8764e-f110-405f-aa1c-70af4ec9b064", "type": "concept", "title": "Metropolitan labor markets"}, {"id": "973ee1af-bcc7-4ae9-af30-24dcc2691df3", "type": "concept", "title": "Regional fragmentation"}], "description": "Urban sociology treats cities as regions of commuting, housing, services, governance, and inequality."}, {"id": "c4c46e07-8df5-45c8-b120-5c25f1664d8e", "type": "subtopic", "title": "Comparative urbanization", "children": [{"id": "b3a3f55f-7097-4ea7-849b-fa11280396f3", "type": "concept", "title": "Global North and Global South"}, {"id": "acef0aa9-72cb-484a-adff-5b16b179631b", "type": "concept", "title": "Informal urbanization"}, {"id": "4687e095-86af-4e79-8aff-efe2a4e80b4c", "type": "concept", "title": "Colonial and postcolonial city forms"}], "description": "Comparing cities prevents treating one national pattern as universal."}]}, {"id": "58acfde8-2993-44d9-b46f-28452841acc3", "type": "topic", "title": "Classical Urban Theory and the Chicago School", "description": "Classical urban theory gives students foundational language for urban ecology, social disorganization, community, anonymity, and metropolitan culture.", "children": [{"id": "e90a9577-444d-4535-8854-e3983c90105f", "type": "subtopic", "title": "Chicago School urban ecology", "children": [{"id": "aefb37da-044a-4f09-a3c1-d411bae9b971", "type": "concept", "title": "Concentric zone model"}, {"id": "c5ce3cfa-0a87-44fa-9bcd-f4f660e7529d", "type": "concept", "title": "Invasion and succession"}, {"id": "80ab2bc0-508f-4a06-8634-cdd41da9344c", "type": "concept", "title": "Natural areas"}], "description": "Students learn how early sociologists linked urban space to social organization."}, {"id": "7c6efcad-aba1-46df-9ba6-5d4469835a28", "type": "subtopic", "title": "Simmel, Wirth, and urbanism", "children": [{"id": "a0b1aa61-c217-4e28-b721-d2e7a97cb52e", "type": "concept", "title": "Blase attitude"}, {"id": "20bb19b2-012c-4c38-92d1-40410d4b80bb", "type": "concept", "title": "Urbanism as way of life"}, {"id": "846263db-3b9f-439c-9f6d-d2d3cf181bc5", "type": "concept", "title": "Density, size, and heterogeneity"}], "description": "Classical theory asks how metropolitan life changes social interaction and identity."}, {"id": "100ffac7-6071-4166-a6df-c02df171430f", "type": "subtopic", "title": "Critiques and revisions", "children": [{"id": "2c69a54c-3955-4630-9063-987c15e486bf", "type": "concept", "title": "Ecological determinism"}, {"id": "8ce7b7d0-71d9-41f7-872a-a32a931a7ff1", "type": "concept", "title": "Race and segregation"}, {"id": "f3744ea6-d705-4773-981f-ffc93086f5c9", "type": "concept", "title": "From community studies to political economy"}], "description": "Students evaluate how classical models understate race, power, policy, and political economy."}]}, {"id": "59c7c7a5-aea3-4798-865a-9dcf8b2a7c7f", "type": "topic", "title": "Political Economy of Cities", "description": "Urban space is produced through markets, states, capital, labor, and land. Students examine the city as a site of accumulation, conflict, and governance.", "children": [{"id": "e0caa2c0-71ae-4685-b35a-596645843ab9", "type": "subtopic", "title": "Urban land and capital", "children": [{"id": "80bbf585-9315-4b77-9e3a-27f677314db1", "type": "concept", "title": "Rent gap"}, {"id": "e1c9d2f3-0aa1-4d0a-b215-c0f9d3c70476", "type": "concept", "title": "Real estate finance"}, {"id": "b6f1a4bb-c173-4b0b-bd48-c5ae5b410235", "type": "concept", "title": "Speculation and redevelopment"}], "description": "Land markets organize who can live, work, and invest in particular places."}, {"id": "ca745179-d0da-44bc-ad97-e98e347e9152", "type": "subtopic", "title": "Growth machines and regimes", "children": [{"id": "6c1abbe2-e904-44bf-809d-4cc4eaee0aee", "type": "concept", "title": "Urban growth machine"}, {"id": "ae6f794a-18e5-4682-964f-8693773a5d1a", "type": "concept", "title": "Urban regime theory"}, {"id": "0e7b2fd1-e25a-48a7-83aa-f8f1fbdbb142", "type": "concept", "title": "Public-private partnerships"}], "description": "Local politics often reflects coalitions seeking growth, revenue, and prestige."}, {"id": "6ca6f936-d5af-4d02-8a06-41286dcf1d75", "type": "subtopic", "title": "Neoliberal urbanism", "children": [{"id": "5105f281-b1e9-4e82-8e59-4c16f6202f54", "type": "concept", "title": "Tax incentives"}, {"id": "d639b619-f859-458f-bf70-695d18aed8ef", "type": "concept", "title": "Mega-projects"}, {"id": "e17a77cb-80bc-408b-b7ba-ca830604885c", "type": "concept", "title": "Austerity and service cuts"}], "description": "Students analyze privatization, austerity, entrepreneurial governance, and competitive city branding."}]}, {"id": "29eb46a6-3da5-433b-abc8-f5068d69f76c", "type": "topic", "title": "Suburbanization, Sprawl, and Metropolitan Fragmentation", "description": "Suburbs are central to urban sociology, not outside it. This topic examines how suburbanization reorganized race, class, family life, transportation, taxation, and political boundaries.", "children": [{"id": "473921bd-e71c-4405-8c49-8e5a732a2509", "type": "subtopic", "title": "Postwar suburbanization", "children": [{"id": "28ef5164-07a2-4620-b186-b36cfb3afbae", "type": "concept", "title": "Mortgage markets"}, {"id": "083631d8-123f-4ea4-b4e1-6c68fc526f45", "type": "concept", "title": "Highway construction"}, {"id": "c83c38f3-055c-4b56-b09e-0856dc855496", "type": "concept", "title": "White flight and exclusionary suburbs"}], "description": "Students study how policy, finance, highways, and racial exclusion shaped suburban growth."}, {"id": "b9f862a1-26cc-4f27-b336-9cb4e07a2c83", "type": "subtopic", "title": "Sprawl and auto dependence", "children": [{"id": "5ab5d6c7-825e-4af6-af7a-da62b2b43ebb", "type": "concept", "title": "Low-density development"}, {"id": "f9bca9c4-8760-425d-a6a7-19822103fc8b", "type": "concept", "title": "Zoning and parking"}, {"id": "6871c8fa-59ff-41e5-a8cc-8ca18a09e2ca", "type": "concept", "title": "Commute burdens"}], "description": "Built form shapes access to jobs, services, time, health, and environmental exposure."}, {"id": "085a705a-31aa-423b-a671-3bdd9d19c690", "type": "subtopic", "title": "Suburban diversity and poverty", "children": [{"id": "195c69ea-daa1-4e33-a84f-191360289b07", "type": "concept", "title": "Immigrant suburbs"}, {"id": "6ef80eb1-19df-4f72-b6a9-ab9e6375197b", "type": "concept", "title": "Suburban poverty"}, {"id": "ff105efb-5b83-44b8-af9e-343202b9565e", "type": "concept", "title": "Edge cities and job decentralization"}], "description": "Contemporary suburbs are increasingly diverse and unequal."}]}, {"id": "54846142-4403-4c0e-977f-0782d440cf73", "type": "topic", "title": "Neighborhoods, Community, and Everyday Urban Life", "description": "Neighborhoods are more than containers for people: they shape networks, identity, belonging, safety, opportunity, and stigma.", "children": [{"id": "65f69292-eac5-41b0-9d29-8a446cdaa761", "type": "subtopic", "title": "Neighborhood effects", "children": [{"id": "cd21b0bf-22b9-4bb0-990c-951ebe2eecb6", "type": "concept", "title": "Social networks"}, {"id": "bb92ad16-099b-4297-9b49-1d191340af25", "type": "concept", "title": "Collective efficacy"}, {"id": "dfc5e03c-d961-4773-afd5-352c6a8dbb0c", "type": "concept", "title": "Selection and contextual effects"}], "description": "Students learn how place may influence outcomes while avoiding simplistic causal claims."}, {"id": "ea5dc250-a452-4d9e-a173-d856eecc6848", "type": "subtopic", "title": "Community and social ties", "children": [{"id": "9fcb25a8-a122-451e-a343-1697cb34accc", "type": "concept", "title": "Weak ties"}, {"id": "de1bb42b-033a-4d72-8481-9f0c58b7a308", "type": "concept", "title": "Public familiarity"}, {"id": "b9a518a8-8206-4baa-a90e-a9e3d4f28051", "type": "concept", "title": "Community organizations"}], "description": "Urban life includes both anonymity and dense forms of local connection."}, {"id": "7f1c2ed3-010f-4b89-af90-87c1afa94172", "type": "subtopic", "title": "Stigma and place reputation", "children": [{"id": "67b2ba1d-1243-4135-b02d-c7b552773a62", "type": "concept", "title": "Territorial stigma"}, {"id": "c193696c-3ce3-48c5-884f-d731ab7465b0", "type": "concept", "title": "Media narratives"}, {"id": "669ef4aa-08b5-4dbf-8f1a-1f234951f7ff", "type": "concept", "title": "Place-based identity and resistance"}], "description": "Neighborhood labels affect investment, policing, mobility, and resident identity."}]}, {"id": "ab87b69d-ae70-4491-ad43-0ec4bc73cfd9", "type": "topic", "title": "Segregation, Race, and Spatial Inequality", "description": "Segregation is a core mechanism of urban inequality. Students examine how race, class, housing, schools, policing, and policy become spatially organized.", "children": [{"id": "bd3ee9ba-7bb3-43d0-868a-e2aa5b3866d9", "type": "subtopic", "title": "Residential segregation", "children": [{"id": "ef284c98-d460-4e51-835c-23302ea9f2c6", "type": "concept", "title": "Dissimilarity and isolation indexes"}, {"id": "a999306d-2794-41c1-a1d3-4d1bf2ab6c5d", "type": "concept", "title": "Redlining and restrictive covenants"}, {"id": "53082fed-6847-43e0-ba81-03362703c5b0", "type": "concept", "title": "Steering and discrimination"}], "description": "Students learn how segregation is produced and measured."}, {"id": "a57c5e7b-9d67-437c-9d98-f65a06926de5", "type": "subtopic", "title": "Institutional racism in urban space", "children": [{"id": "f55b6385-eb70-4c86-8788-2ebd61f59270", "type": "concept", "title": "Schools and tax bases"}, {"id": "65afe2ff-e170-4766-b9e1-3b8baa59d7f8", "type": "concept", "title": "Policing and punishment"}, {"id": "ee3e794d-65fa-4576-ae59-352d86eb0b9e", "type": "concept", "title": "Environmental burdens"}], "description": "Urban institutions create unequal exposure to opportunity and harm."}, {"id": "e6f25227-8b75-4184-8b11-af05cfb0f222", "type": "subtopic", "title": "Mobility and opportunity", "children": [{"id": "f6a2cc20-4076-4f77-8b5b-55d831618235", "type": "concept", "title": "Opportunity Insights"}, {"id": "6c5fff5c-bf47-4358-8ad4-b3a721f75975", "type": "concept", "title": "Spatial mismatch"}, {"id": "3f9f631f-7520-4bca-9fec-5b7338b63439", "type": "concept", "title": "Place-based and mobility policies"}], "description": "Students analyze how neighborhoods shape access to education, jobs, networks, and health."}]}, {"id": "d77bcc1c-b857-44e3-9d08-f9f0df49aff4", "type": "topic", "title": "Housing Markets, Affordability, and Homelessness", "description": "Housing is both shelter and a commodity. Students study rent, ownership, displacement, housing policy, eviction, homelessness, and the politics of land use.", "children": [{"id": "d6a2ff2d-7af3-4d11-affd-38bd9fe9ebab", "type": "subtopic", "title": "Housing affordability", "children": [{"id": "44ab0855-4a88-4b67-a07f-ff30c8dd1660", "type": "concept", "title": "Rent burden"}, {"id": "cc414828-6308-4a2f-98bb-3e5ef3c7d6d9", "type": "concept", "title": "Supply and demand debates"}, {"id": "a34b0190-0773-413b-888e-98c78fd9b3ec", "type": "concept", "title": "Wages, zoning, and speculation"}], "description": "Students examine why housing costs rise and who is most affected."}, {"id": "09bbe5c8-c441-46db-9f36-ddefef53ade3", "type": "subtopic", "title": "Eviction and housing insecurity", "children": [{"id": "7ba51862-232d-4df8-8c38-c77598939090", "type": "concept", "title": "Eviction process"}, {"id": "ee96467d-a298-4205-822a-950da532813b", "type": "concept", "title": "Informal displacement"}, {"id": "97e5c23b-60a1-412f-86fa-d72f8dfd16fe", "type": "concept", "title": "Tenant protections"}], "description": "Housing instability reveals the relationship between poverty, law, landlords, and public policy."}, {"id": "28bbc7e8-374a-4af0-952e-088a75a2d702", "type": "subtopic", "title": "Homelessness and housing policy", "children": [{"id": "12804602-aa32-4478-8439-1ed6b4b4f0ae", "type": "concept", "title": "Housing First"}, {"id": "84462a65-32c1-41ff-89c8-716601a8874a", "type": "concept", "title": "Shelters and encampments"}, {"id": "f2a2ed66-6a20-43a8-a0b0-055cff6aa135", "type": "concept", "title": "Public, nonprofit, and market roles"}], "description": "Students compare responses to homelessness and housing precarity."}]}, {"id": "14fa7fe6-7d25-4072-ae6e-65cbe3be171b", "type": "topic", "title": "Gentrification, Displacement, and Neighborhood Change", "description": "Gentrification forces students to confront the uneven effects of reinvestment. The goal is to analyze change without romanticizing either decline or redevelopment.", "children": [{"id": "d397caad-6670-4f42-a8e4-557c5f433e5b", "type": "subtopic", "title": "Gentrification theories", "children": [{"id": "71e7eaf0-7c4c-44ea-9542-fd291aea48a9", "type": "concept", "title": "Rent gap theory"}, {"id": "457dc92f-2ac4-45aa-87a4-6b5e84f1fad4", "type": "concept", "title": "Middle-class cultural consumption"}, {"id": "a59d15de-106b-43b4-b326-66b5e0fefef1", "type": "concept", "title": "State-led redevelopment"}], "description": "Students compare production-side and consumption-side explanations."}, {"id": "72790f45-5e46-4265-9b1f-140be8b65f1a", "type": "subtopic", "title": "Displacement and cultural change", "children": [{"id": "3a97a858-eca0-4c0c-b645-65358fac0f12", "type": "concept", "title": "Physical displacement"}, {"id": "d6a809fe-b31f-49db-8587-1337ad771e97", "type": "concept", "title": "Commercial and cultural displacement"}, {"id": "db112a6a-5cdb-41a9-8d9d-53a858f8dda9", "type": "concept", "title": "Loss of belonging"}], "description": "Displacement can be direct, indirect, economic, cultural, and political."}, {"id": "ae0edbbb-b251-4539-b118-413a22941c52", "type": "subtopic", "title": "Policy responses", "children": [{"id": "4303bab8-330d-42f6-8a37-be88089cd690", "type": "concept", "title": "Inclusionary zoning"}, {"id": "c54b1ee1-afe9-4aa9-a1a2-f79574c4b124", "type": "concept", "title": "Community land trusts"}, {"id": "e2ac402e-c580-463d-9086-481b6e41121c", "type": "concept", "title": "Rent regulation and anti-displacement policy"}], "description": "Students evaluate tools intended to prevent exclusion while enabling investment."}]}, {"id": "9d7f5bd0-e4ca-4705-93cc-f483bb915da4", "type": "topic", "title": "Urban Culture, Public Space, and Street Life", "description": "Cities produce distinctive cultures through density, diversity, creativity, public space, and everyday interaction. Students study the social life of streets, parks, transit, nightlife, and informal economies.", "children": [{"id": "d476df4c-0d6f-4884-833c-e2c0f76136eb", "type": "subtopic", "title": "Public space and social interaction", "children": [{"id": "45ec9363-5900-4f89-8c10-289ce7925868", "type": "concept", "title": "Street life"}, {"id": "6e14cfd9-f028-4840-9342-74e9bfd08e0c", "type": "concept", "title": "Parks and plazas"}, {"id": "1ce1ccd5-bf6c-41d0-b8a7-b9a02758be82", "type": "concept", "title": "Loitering, policing, and access"}], "description": "Public spaces reveal norms of belonging, exclusion, surveillance, and encounter."}, {"id": "c1824489-916e-4e8e-9eb4-6acb91e7d829", "type": "subtopic", "title": "Urban culture and creative economies", "children": [{"id": "72ffb9cc-aa43-49e9-ab7b-89809f6e4497", "type": "concept", "title": "Scenes and subcultures"}, {"id": "7425c590-532e-4d3c-a9c5-c5bfed30a9ea", "type": "concept", "title": "Arts districts"}, {"id": "9991a322-e666-444a-8198-5faf7b3207f4", "type": "concept", "title": "Cultural capital and creative cities"}], "description": "Culture can empower communities and also become an engine of branding and displacement."}, {"id": "fe85794c-fcbc-4cc8-9a35-6fcc27f6abc1", "type": "subtopic", "title": "Informal urban life", "children": [{"id": "da609dc3-aba2-4021-a7e7-6104923347a4", "type": "concept", "title": "Street vending"}, {"id": "a48601fd-ec72-4aa4-abec-9aa2aea93c11", "type": "concept", "title": "Mutual aid"}, {"id": "e58cc5ad-fbd3-4825-a592-a4d82d660fce", "type": "concept", "title": "Informal transport and services"}], "description": "Informal practices show how residents make cities work beyond official plans."}]}, {"id": "113deac2-2e8b-4082-b808-acf4a4ffee2b", "type": "topic", "title": "Urban Politics, Governance, and Local Power", "description": "Urban politics shapes budgets, services, policing, land use, infrastructure, and who gets heard. Students examine local power as both democratic and unequal.", "children": [{"id": "3e5221ee-b944-42e8-9e20-3ce04251489e", "type": "subtopic", "title": "Local government structures", "children": [{"id": "52e72abf-4762-457a-be56-d2db5a5bf962", "type": "concept", "title": "Mayors, councils, managers, and agencies"}, {"id": "838e7056-9f5e-4163-9b30-e4726348aa71", "type": "concept", "title": "Special districts"}, {"id": "6f9b8a97-2e3c-4b88-bb23-d0417718709a", "type": "concept", "title": "Metropolitan fragmentation"}], "description": "Students learn the institutional landscape of urban governance."}, {"id": "5ecf57a7-f7e7-47e4-9367-277f5f1c7d34", "type": "subtopic", "title": "Participation and representation", "children": [{"id": "e0ca7ba9-4421-4b4b-b0a0-9e3356652c4f", "type": "concept", "title": "Community boards"}, {"id": "8469ca5a-e4b7-4f68-a26d-f300f16b2ffc", "type": "concept", "title": "Public hearings"}, {"id": "18ccc119-4c0d-43bb-bb68-97f836396a4b", "type": "concept", "title": "NIMBY, YIMBY, and organizing"}], "description": "Local democracy is shaped by turnout, advocacy, expertise, and unequal voice."}, {"id": "41109a28-9a93-4e75-8469-e498a70e1461", "type": "subtopic", "title": "Fiscal stress and service delivery", "children": [{"id": "b0992218-ded2-4b9c-af2c-49dc14af134d", "type": "concept", "title": "Tax bases"}, {"id": "925eae08-46b3-40e0-b25c-7b550f8efed3", "type": "concept", "title": "Municipal debt"}, {"id": "468335a1-b002-4a98-8676-9a306e8529a9", "type": "concept", "title": "Service inequality"}], "description": "Urban inequality is tied to revenue, mandates, austerity, and administrative capacity."}]}, {"id": "a8aab966-06e9-4f5f-a395-302230ac0f43", "type": "topic", "title": "Transportation, Infrastructure, and Mobility Justice", "description": "Infrastructure organizes the rhythms and possibilities of urban life. Students study mobility as a question of access, time, safety, environment, and justice.", "children": [{"id": "6d38b6c2-a627-40bc-ac0c-b15850e9bbe8", "type": "subtopic", "title": "Transportation systems", "children": [{"id": "56bad876-2b90-4c32-b485-afc94aa1da8b", "type": "concept", "title": "Transit networks"}, {"id": "048b4407-d5a3-451e-9dae-e8203c950db6", "type": "concept", "title": "Car dependence"}, {"id": "c19a3450-ef40-41f0-b6e2-dc18a3492c2d", "type": "concept", "title": "First-mile and last-mile access"}], "description": "Students compare transit, walking, cycling, driving, and micromobility as social systems."}, {"id": "6e41535f-771a-4473-9485-3aea95d4530d", "type": "subtopic", "title": "Mobility inequality", "children": [{"id": "6bc17472-4e73-43b3-977f-3622c0e5f771", "type": "concept", "title": "Transit deserts"}, {"id": "f7da44ac-20bf-48ba-876f-f7c7a4b0112e", "type": "concept", "title": "Disability access"}, {"id": "0cd7b2b6-a452-466f-a3dc-1d84c1b5720d", "type": "concept", "title": "Gendered and racialized mobility"}], "description": "Unequal mobility constrains work, care, education, health, and civic life."}, {"id": "d40ff456-f344-482e-9879-fcc32f2ee5eb", "type": "subtopic", "title": "Infrastructure politics", "children": [{"id": "b5851664-0605-4881-b6f0-fab214f87931", "type": "concept", "title": "Highway removal"}, {"id": "67904a77-f4a4-4b6c-8235-6e448c1c82f5", "type": "concept", "title": "Asset management"}, {"id": "397ccaef-0e6f-450b-b460-51f4ab44476c", "type": "concept", "title": "Public investment and maintenance"}], "description": "Infrastructure decisions distribute benefits and burdens for decades."}]}, {"id": "2ce41552-9d2c-437e-aa85-1f76ae56a0f1", "type": "topic", "title": "Urban Health, Environment, and Climate Resilience", "description": "Urban environments shape health through housing, pollution, heat, stress, food access, violence, and climate risk. Students connect urban sociology to environmental justice and public health.", "children": [{"id": "3cfe973a-ed05-4cb1-ae2e-43d10da41689", "type": "subtopic", "title": "Social determinants of urban health", "children": [{"id": "7515b469-671b-4434-a24c-31b96baef6d5", "type": "concept", "title": "Housing quality"}, {"id": "9d4bb46a-9f25-4ea3-a1e0-c628880d11d6", "type": "concept", "title": "Food and healthcare access"}, {"id": "98644c3b-53fc-4b05-aa6e-bb8d8530e29e", "type": "concept", "title": "Stress and neighborhood conditions"}], "description": "Students learn how place structures exposure, vulnerability, and wellbeing."}, {"id": "d545ba82-fce4-4ae6-807f-8cc33424dfab", "type": "subtopic", "title": "Environmental justice", "children": [{"id": "b49f5f5c-d7fb-4bd3-8272-08ae0a8ea1eb", "type": "concept", "title": "Air pollution"}, {"id": "23901a65-a9c2-43f0-9270-8aaebaa70772", "type": "concept", "title": "Toxic exposure"}, {"id": "c9316877-e22e-44a3-ad6f-98f9e0123a3d", "type": "concept", "title": "Green space inequality"}], "description": "Environmental harms are unevenly distributed by race, class, and political power."}, {"id": "19fc75e0-5691-49f8-a5b7-f0bc58f13e77", "type": "subtopic", "title": "Climate urbanism", "children": [{"id": "4d8d8561-318f-4923-9533-68c7b8d0f271", "type": "concept", "title": "Urban heat islands"}, {"id": "3cf2839a-6783-46be-82ec-839571c83cd7", "type": "concept", "title": "Resilience planning"}, {"id": "32f8bbeb-f522-4959-b43f-83d2c6b80157", "type": "concept", "title": "Climate gentrification"}], "description": "Cities face heat, flooding, displacement, and adaptation challenges."}]}, {"id": "4f507c4f-c144-4be4-ae34-8e8dccfe2fbd", "type": "topic", "title": "Immigration, Ethnicity, and Transnational Urbanism", "description": "Cities are arrival points, gateways, and transnational hubs. Students study immigrant neighborhoods, ethnic economies, belonging, and exclusion.", "children": [{"id": "0074294a-f7fb-477b-be46-a7a71d36eb17", "type": "subtopic", "title": "Immigrant urban settlement", "children": [{"id": "2220ec61-5aaf-4ab3-a07d-cb6c1943f4ec", "type": "concept", "title": "Gateway cities"}, {"id": "19a0569a-7f53-42f8-b3ed-9be5424b6107", "type": "concept", "title": "Ethnic enclaves"}, {"id": "73af9b6e-9ec3-4cbe-9d3d-167966ee554c", "type": "concept", "title": "Legal status and services"}], "description": "Students examine how migrants build communities and navigate institutions."}, {"id": "be000383-678f-4fc1-a090-5889bacf8638", "type": "subtopic", "title": "Ethnic economies and networks", "children": [{"id": "3d2ae637-1cd5-4bf7-9fdb-e52253514d47", "type": "concept", "title": "Small businesses"}, {"id": "0916b147-c6d0-48a3-b742-428bfecf6aff", "type": "concept", "title": "Labor niches"}, {"id": "4e06ef22-99ff-42e7-b522-4ff5c1ffbe48", "type": "concept", "title": "Remittances and transnational households"}], "description": "Urban economies rely on immigrant labor, entrepreneurship, and transnational ties."}, {"id": "f1690872-faff-455a-9bf4-9552dc0ed7dc", "type": "subtopic", "title": "Belonging and conflict", "children": [{"id": "a9824515-61ea-4238-a319-cbefdc8dee35", "type": "concept", "title": "Sanctuary cities"}, {"id": "901a4ce5-116a-439b-84c6-0dfe24dcb778", "type": "concept", "title": "Nativism and local conflict"}, {"id": "815dc502-38d8-448c-8052-924b09279b97", "type": "concept", "title": "Multicultural public space"}], "description": "Migration reshapes urban culture and politics."}]}, {"id": "43fc5304-0298-49ab-99df-766601715f97", "type": "topic", "title": "Global Cities and Planetary Urbanization", "description": "Urban sociology now studies cities as nodes in global systems of finance, migration, logistics, culture, and governance. Students learn to compare cities across unequal global relations.", "children": [{"id": "8710ff79-666b-4318-84a5-92b6fabb51ee", "type": "subtopic", "title": "Global city theory", "children": [{"id": "324df40b-759a-4d2b-8510-72cab529220f", "type": "concept", "title": "Sassen and global cities"}, {"id": "be692a73-621e-4c31-b0fc-e06a7c26fc30", "type": "concept", "title": "Finance and advanced services"}, {"id": "d1cc1f93-820b-47ef-b0fd-e4438763c9a5", "type": "concept", "title": "Global city hierarchies"}], "description": "Students analyze how command functions, finance, and producer services concentrate in some cities."}, {"id": "2f140f68-70a2-4fea-9a47-c61e28cd3e0d", "type": "subtopic", "title": "Informality and mega-urbanization", "children": [{"id": "a2f5112f-8290-4bd4-928c-8dd5b158ebb9", "type": "concept", "title": "Slums and informal settlements"}, {"id": "9f784a90-d7d9-4d84-aefa-cc2c94e0089e", "type": "concept", "title": "Informal economies"}, {"id": "0c6f6d45-cc5e-40f7-8ef4-acd089f9beb9", "type": "concept", "title": "Service gaps and self-provisioning"}], "description": "Global urban growth often includes informal settlement, informal labor, and uneven infrastructure."}, {"id": "060165c3-dafc-47c9-9412-63d4de1f678b", "type": "subtopic", "title": "Planetary urbanization", "children": [{"id": "86844cab-7d5d-4e52-8e07-63be0f05bdaf", "type": "concept", "title": "Supply chains"}, {"id": "68a34fec-5728-441e-83d6-67e5db5c0867", "type": "concept", "title": "Resource hinterlands"}, {"id": "65ecc6c0-64d4-4f6a-bbbc-5dee3cdfea5b", "type": "concept", "title": "Logistics, extraction, and ecological footprints"}], "description": "Urban processes now extend far beyond city boundaries."}]}, {"id": "277833c8-b121-44d4-8705-78adfa346fbc", "type": "topic", "title": "Urban Data, GIS, and Spatial Methods", "description": "A world-class urban sociology course trains students to use maps and data critically. Students learn that spatial analysis is powerful, but never neutral.", "children": [{"id": "a310be75-bbe2-44c3-bd36-1fb2c733d005", "type": "subtopic", "title": "Neighborhood data literacy", "children": [{"id": "f15eebe4-d2e1-4deb-9689-5141584305ee", "type": "concept", "title": "Census and ACS"}, {"id": "52ddea9b-c5c1-4c10-91d7-2fce0c093b4f", "type": "concept", "title": "Data2Go.NYC"}, {"id": "fe417aa3-37d7-4e97-8646-c478a0e68c9a", "type": "concept", "title": "Administrative data and open data portals"}], "description": "Students work with demographic, housing, health, education, and mobility data."}, {"id": "4ab5e028-7505-40e7-bcda-f602a535cd3a", "type": "subtopic", "title": "Mapping and GIS basics", "children": [{"id": "3f554663-e5ee-4314-87ab-dac27e2eaed3", "type": "concept", "title": "Choropleth maps"}, {"id": "bfacb9cc-8016-4329-b48d-dca73be65764", "type": "concept", "title": "Scale and aggregation"}, {"id": "18d05b2d-0ba3-41e9-945d-86192fae4cb9", "type": "concept", "title": "Modifiable areal unit problem"}], "description": "Maps help reveal patterns and can also hide assumptions."}, {"id": "80d242a1-3837-4487-8047-44839680b594", "type": "subtopic", "title": "Fieldwork and mixed methods", "children": [{"id": "4ff4ea8e-3e28-4dbb-b240-ef9dd1725fea", "type": "concept", "title": "Street observation"}, {"id": "5b43ad3a-f777-42ea-afe6-8c4fd2a3ddf0", "type": "concept", "title": "Transect walks"}, {"id": "cdb7726d-8903-4c0a-b117-e7c13a1e8d78", "type": "concept", "title": "Photo and built-environment audits"}], "description": "Urban research combines observation, interviews, archival work, data, and maps."}]}, {"id": "3f923b42-e014-44ef-a795-b3e845f32c88", "type": "topic", "title": "Urban Policy, Planning, and Social Change", "description": "Urban policy translates conflicts over land, housing, transport, safety, climate, and public space into decisions. Students learn to evaluate policy tools and their distributional consequences.", "children": [{"id": "81c694ae-d939-4318-84c5-dc7bec8149ba", "type": "subtopic", "title": "Policy tools and governance", "children": [{"id": "e1c2619f-0916-40a3-a377-9ee0951156e5", "type": "concept", "title": "Zoning and land use"}, {"id": "8df584a0-ff15-49ba-90ee-402f68f1d858", "type": "concept", "title": "Housing subsidies"}, {"id": "55809e3e-9c68-4b31-b875-0e3647929f77", "type": "concept", "title": "Infrastructure and public services"}], "description": "Students compare local, regional, state, federal, nonprofit, and market interventions."}, {"id": "5928c5fa-d1fd-4963-bd14-83f76903eab3", "type": "subtopic", "title": "Equity-centered planning", "children": [{"id": "e47f1b49-c040-438e-b0db-21952ce9b33d", "type": "concept", "title": "Community benefits agreements"}, {"id": "fb27a1b3-47dd-4668-babb-1d05983bc049", "type": "concept", "title": "Participatory planning"}, {"id": "437755fb-e39a-4d08-9a4b-dada36bd1993", "type": "concept", "title": "Racial equity impact assessment"}], "description": "Planning can repair harm or reproduce inequality depending on process and power."}, {"id": "6365c602-4f2c-46cf-a8dc-bc6a0cb61110", "type": "subtopic", "title": "Urban policy proposal", "children": [{"id": "e4c2c499-c0e9-490f-aa9e-d283d23e9b28", "type": "concept", "title": "Problem definition"}, {"id": "768eb121-872b-448d-9b8a-a1f92457a6d9", "type": "concept", "title": "Stakeholder analysis"}, {"id": "5cebc75e-366a-4dc1-98c2-da7fa670957e", "type": "concept", "title": "Implementation and evaluation plan"}], "description": "Students synthesize sociology and policy into a realistic intervention."}]}, {"id": "d6639f40-56fd-42be-b9ad-ababafd29b81", "type": "topic", "title": "Capstone: Comparative Urban Case Study", "description": "The final topic asks students to bring theory, data, field observation, and policy analysis together in a polished urban case study.", "children": [{"id": "3aa5931f-cc31-40a5-9011-cbf9783e9847", "type": "subtopic", "title": "Case selection and research question", "children": [{"id": "72ed12a6-3a7c-49ff-9b0e-028ad90f4a24", "type": "concept", "title": "Comparative logic"}, {"id": "be37e9bc-8cc1-446a-975c-03632ba7b253", "type": "concept", "title": "Scope and feasibility"}, {"id": "ed5100a4-6bfe-4ad9-a2cd-077018747731", "type": "concept", "title": "Ethics and positionality"}], "description": "Students choose a neighborhood, city, corridor, policy, or urban conflict that can be studied with evidence."}, {"id": "38046150-cc24-47e5-af65-b5845895bc41", "type": "subtopic", "title": "Evidence portfolio", "children": [{"id": "53979948-f560-41a9-b23f-176051bb9373", "type": "concept", "title": "Maps and statistics"}, {"id": "09cd8cc8-7038-4b57-ac66-76f155c5bf8c", "type": "concept", "title": "Policy documents"}, {"id": "1ff36c24-cbae-47a6-b935-715c48c862b4", "type": "concept", "title": "Observation, media, and interviews"}], "description": "Students assemble multiple forms of evidence rather than relying on one data point."}, {"id": "38a6054f-c487-475c-8833-f96ab039cb3d", "type": "subtopic", "title": "Public presentation", "children": [{"id": "40a9a3ab-5a1d-45e4-bd73-68e549fd7bb6", "type": "concept", "title": "Visual argument"}, {"id": "525584b9-23a5-4275-a2d4-abbf3af99f1d", "type": "concept", "title": "Policy implications"}, {"id": "2b297f41-bc67-4b92-87ad-d34e633dfb43", "type": "concept", "title": "Accessible public scholarship"}], "description": "Students communicate urban findings to academic and public audiences."}]}], "dbBacked": true}$urbsjson$::jsonb,
