  ('cd21b0bf-22b9-4bb0-990c-951ebe2eecb6', 'b3c4d5e6-7f8a-4c03-8d23-4e5f6a7b8c33', '65f69292-eac5-41b0-9d29-8a446cdaa761', 'concept'::public.curated_course_node_type, 'Social networks', null, 0),
