  ('dfc5e03c-d961-4773-afd5-352c6a8dbb0c', 'b3c4d5e6-7f8a-4c03-8d23-4e5f6a7b8c33', '65f69292-eac5-41b0-9d29-8a446cdaa761', 'concept'::public.curated_course_node_type, 'Selection and contextual effects', null, 2),
  ('ea5dc250-a452-4d9e-a173-d856eecc6848', 'b3c4d5e6-7f8a-4c03-8d23-4e5f6a7b8c33', '54846142-4403-4c0e-977f-0782d440cf73', 'subtopic'::public.curated_course_node_type, 'Community and social ties', 'Urban life includes both anonymity and dense forms of local connection.', 1),
  ('9fcb25a8-a122-451e-a343-1697cb34accc', 'b3c4d5e6-7f8a-4c03-8d23-4e5f6a7b8c33', 'ea5dc250-a452-4d9e-a173-d856eecc6848', 'concept'::public.curated_course_node_type, 'Weak ties', null, 0),
  ('de1bb42b-033a-4d72-8481-9f0c58b7a308', 'b3c4d5e6-7f8a-4c03-8d23-4e5f6a7b8c33', 'ea5dc250-a452-4d9e-a173-d856eecc6848', 'concept'::public.curated_course_node_type, 'Public familiarity', null, 1),
  ('b9a518a8-8206-4baa-a90e-a9e3d4f28051', 'b3c4d5e6-7f8a-4c03-8d23-4e5f6a7b8c33', 'ea5dc250-a452-4d9e-a173-d856eecc6848', 'concept'::public.curated_course_node_type, 'Community organizations', null, 2),
  ('7f1c2ed3-010f-4b89-af90-87c1afa94172', 'b3c4d5e6-7f8a-4c03-8d23-4e5f6a7b8c33', '54846142-4403-4c0e-977f-0782d440cf73', 'subtopic'::public.curated_course_node_type, 'Stigma and place reputation', 'Neighborhood labels affect investment, policing, mobility, and resident identity.', 2),
  ('67b2ba1d-1243-4135-b02d-c7b552773a62', 'b3c4d5e6-7f8a-4c03-8d23-4e5f6a7b8c33', '7f1c2ed3-010f-4b89-af90-87c1afa94172', 'concept'::public.curated_course_node_type, 'Territorial stigma', null, 0),
  ('c193696c-3ce3-48c5-884f-d731ab7465b0', 'b3c4d5e6-7f8a-4c03-8d23-4e5f6a7b8c33', '7f1c2ed3-010f-4b89-af90-87c1afa94172', 'concept'::public.curated_course_node_type, 'Media narratives', null, 1),
  ('669ef4aa-08b5-4dbf-8f1a-1f234951f7ff', 'b3c4d5e6-7f8a-4c03-8d23-4e5f6a7b8c33', '7f1c2ed3-010f-4b89-af90-87c1afa94172', 'concept'::public.curated_course_node_type, 'Place-based identity and resistance', null, 2),
  ('ab87b69d-ae70-4491-ad43-0ec4bc73cfd9', 'b3c4d5e6-7f8a-4c03-8d23-4e5f6a7b8c33', null, 'topic'::public.curated_course_node_type, 'Segregation, Race, and Spatial Inequality', 'Segregation is a core mechanism of urban inequality. Students examine how race, class, housing, schools, policing, and policy become spatially organized.', 6),
