  ('44ab0855-4a88-4b67-a07f-ff30c8dd1660', 'b3c4d5e6-7f8a-4c03-8d23-4e5f6a7b8c33', 'd6a2ff2d-7af3-4d11-affd-38bd9fe9ebab', 'concept'::public.curated_course_node_type, 'Rent burden', null, 0),
