  ('52e72abf-4762-457a-be56-d2db5a5bf962', 'b3c4d5e6-7f8a-4c03-8d23-4e5f6a7b8c33', '3e5221ee-b944-42e8-9e20-3ce04251489e', 'concept'::public.curated_course_node_type, 'Mayors, councils, managers, and agencies', null, 0),
