  ('468335a1-b002-4a98-8676-9a306e8529a9', 'b3c4d5e6-7f8a-4c03-8d23-4e5f6a7b8c33', '41109a28-9a93-4e75-8469-e498a70e1461', 'concept'::public.curated_course_node_type, 'Service inequality', null, 2),
  ('a8aab966-06e9-4f5f-a395-302230ac0f43', 'b3c4d5e6-7f8a-4c03-8d23-4e5f6a7b8c33', null, 'topic'::public.curated_course_node_type, 'Transportation, Infrastructure, and Mobility Justice', 'Infrastructure organizes the rhythms and possibilities of urban life. Students study mobility as a question of access, time, safety, environment, and justice.', 11),
