  ('56bad876-2b90-4c32-b485-afc94aa1da8b', 'b3c4d5e6-7f8a-4c03-8d23-4e5f6a7b8c33', '6d38b6c2-a627-40bc-ac0c-b15850e9bbe8', 'concept'::public.curated_course_node_type, 'Transit networks', null, 0),
  ('048b4407-d5a3-451e-9dae-e8203c950db6', 'b3c4d5e6-7f8a-4c03-8d23-4e5f6a7b8c33', '6d38b6c2-a627-40bc-ac0c-b15850e9bbe8', 'concept'::public.curated_course_node_type, 'Car dependence', null, 1),
