  ('6e41535f-771a-4473-9485-3aea95d4530d', 'b3c4d5e6-7f8a-4c03-8d23-4e5f6a7b8c33', 'a8aab966-06e9-4f5f-a395-302230ac0f43', 'subtopic'::public.curated_course_node_type, 'Mobility inequality', 'Unequal mobility constrains work, care, education, health, and civic life.', 1),
  ('6bc17472-4e73-43b3-977f-3622c0e5f771', 'b3c4d5e6-7f8a-4c03-8d23-4e5f6a7b8c33', '6e41535f-771a-4473-9485-3aea95d4530d', 'concept'::public.curated_course_node_type, 'Transit deserts', null, 0),
