  ('b5851664-0605-4881-b6f0-fab214f87931', 'b3c4d5e6-7f8a-4c03-8d23-4e5f6a7b8c33', 'd40ff456-f344-482e-9879-fcc32f2ee5eb', 'concept'::public.curated_course_node_type, 'Highway removal', null, 0),
  ('67904a77-f4a4-4b6c-8235-6e448c1c82f5', 'b3c4d5e6-7f8a-4c03-8d23-4e5f6a7b8c33', 'd40ff456-f344-482e-9879-fcc32f2ee5eb', 'concept'::public.curated_course_node_type, 'Asset management', null, 1),
  ('397ccaef-0e6f-450b-b460-51f4ab44476c', 'b3c4d5e6-7f8a-4c03-8d23-4e5f6a7b8c33', 'd40ff456-f344-482e-9879-fcc32f2ee5eb', 'concept'::public.curated_course_node_type, 'Public investment and maintenance', null, 2),
  ('2ce41552-9d2c-437e-aa85-1f76ae56a0f1', 'b3c4d5e6-7f8a-4c03-8d23-4e5f6a7b8c33', null, 'topic'::public.curated_course_node_type, 'Urban Health, Environment, and Climate Resilience', 'Urban environments shape health through housing, pollution, heat, stress, food access, violence, and climate risk. Students connect urban sociology to environmental justice and public health.', 12),
  ('3cfe973a-ed05-4cb1-ae2e-43d10da41689', 'b3c4d5e6-7f8a-4c03-8d23-4e5f6a7b8c33', '2ce41552-9d2c-437e-aa85-1f76ae56a0f1', 'subtopic'::public.curated_course_node_type, 'Social determinants of urban health', 'Students learn how place structures exposure, vulnerability, and wellbeing.', 0),
  ('7515b469-671b-4434-a24c-31b96baef6d5', 'b3c4d5e6-7f8a-4c03-8d23-4e5f6a7b8c33', '3cfe973a-ed05-4cb1-ae2e-43d10da41689', 'concept'::public.curated_course_node_type, 'Housing quality', null, 0),
