  ('901a4ce5-116a-439b-84c6-0dfe24dcb778', 'b3c4d5e6-7f8a-4c03-8d23-4e5f6a7b8c33', 'f1690872-faff-455a-9bf4-9552dc0ed7dc', 'concept'::public.curated_course_node_type, 'Nativism and local conflict', null, 1),
